import json
files={'ssl-cert':'scan2-ssl-cert','security-headers':'scan2-security-headers','meta-tags':'scan2-meta-tags','redirect':'scan2-redirect','dns':'scan2-dns'}
out={'observed_on':'2026-11-03','method':'public Apify Store API, narrow queries; users_30d mixes free and paid users; paid share unobservable','jobs':{}}
for job,f in files.items():
  d=json.load(open('/workspace/products/research/'+f+'.json'))
  d=d.get('data',d)
  items=d.get('items',[])
  rows=[]
  for it in items:
    st=it.get('stats') or {}
    pi=it.get('currentPricingInfo') or {}
    ev={}
    for k,v in ((pi.get('pricingPerEvent') or {}).get('actorChargeEvents') or {}).items():
      p=v.get('eventPriceUsd')
      if p is None:
        t=(v.get('eventTieredPricingUsd') or {}).get('FREE') or {}
        p=t.get('tieredEventPriceUsd')
      ev[k]=p
    rows.append({'name':it.get('username','')+'/'+it.get('name',''),'title':it.get('title'),'users_30d':st.get('totalUsers30Days'),'users_total':st.get('totalUsers'),'rating':it.get('actorReviewRating'),'reviews':it.get('actorReviewCount'),'pricing_model':pi.get('pricingModel'),'events':ev})
  rows.sort(key=lambda r:-(r['users_30d'] or 0))
  out['jobs'][job]={'artifact':'products/research/'+f+'.json','total':d.get('total'),'n20plus':sum(1 for r in rows if (r['users_30d'] or 0)>=20),'top5':rows[:5]}
json.dump(out,open('/workspace/products/research/scan2-summary.json','w'),indent=1)
for j,v in out['jobs'].items():
  print(j,v['total'],v['n20plus'],[(r['name'][:40],r['users_30d'],r['pricing_model'],{k:p for k,p in list(r['events'].items())[:2]}) for r in v['top5'][:3]])
